mapper.sql:
SELECT 'LOCAL' AS kind, p.id AS ref_id, p.title AS title, p.difficulty AS difficulty, p.rating AS rating, p.source_id AS source_id, s.name AS source_name, CAST(NULL AS CHAR(512)) AS url, p.submit_count AS submit_count, p.accepted_count AS accepted_count, p.author_id AS author_id, u.nickname AS author_nickname, p.created_at AS created_at FROM problems p LEFT JOIN sources s ON s.id = p.source_id JOIN users u ON u.id = p.author_id WHERE p.status = 'PUBLISHED'
AND p.title LIKE CONCAT('%', #{criteria.keyword}, '%')
AND p.source_id = #{criteria.sourceId}
AND p.difficulty = #{criteria.difficulty}
AND p.rating = #{criteria.rating}
AND p.rating >= #{criteria.minRating}
AND p.rating <= #{criteria.maxRating}
AND EXISTS (SELECT 1 FROM problem_tags pt WHERE pt.problem_id = p.id AND pt.tag_id = #{criteria.tagId})
UNION ALL SELECT 'EXTERNAL' AS kind, e.id AS ref_id, e.title AS title, CAST(NULL AS CHAR(16)) AS difficulty, e.rating AS rating, e.source_id AS source_id, s.name AS source_name, e.url AS url, CAST(NULL AS INTEGER) AS submit_count, CAST(NULL AS INTEGER) AS accepted_count, CAST(NULL AS BIGINT) AS author_id, CAST(NULL AS CHAR(32)) AS author_nickname, e.created_at AS created_at FROM external_problems e JOIN sources s ON s.id = e.source_id WHERE 1 = 1
AND e.title LIKE CONCAT('%', #{criteria.keyword}, '%')
AND e.source_id = #{criteria.sourceId}
AND e.rating = #{criteria.rating}
AND e.rating >= #{criteria.minRating}
AND e.rating <= #{criteria.maxRating}
AND EXISTS (SELECT 1 FROM external_problem_tags et WHERE et.external_problem_id = e.id AND et.tag_id = #{criteria.tagId})

mapper.select:
SELECT c.kind, c.ref_id, c.title, c.difficulty, c.rating, c.source_id, c.source_name, c.url,
       c.submit_count, c.accepted_count, c.author_id, c.author_nickname, c.created_at
FROM (  ) c


        AND c.kind = #{criteria.kind}


ORDER BY c.created_at DESC, c.kind, c.ref_id DESC
LIMIT #{criteria.limit} OFFSET #{criteria.offset}

SELECT COUNT(*)
FROM (  ) c


        AND c.kind = #{criteria.kind}
